const series = data.series.map((s) => {
  const sData = s.fields.find((f) => f.type === 'number').values.buffer || s.fields.find((f) => f.type === 'number').values;
  const sTime = s.fields.find((f) => f.type === 'time').values.buffer || s.fields.find((f) => f.type === 'time').values;

  // Rename legend names
  let legendName = s.refId;
  if (s.refId === 'A') {
    legendName = 'Total Orders';
  } else if (s.refId === 'B') {
    legendName = 'Moving Average';
  }

  if (s.refId === 'A') {
    // Bar chart for Total_count
    return {
      name: legendName, // Use the renamed legend name
      type: 'bar',
      showSymbol: true,
      barMaxWidth: '55%', // Adjust the width as needed
      emphasis: {
        focus: 'series'
      },
      data: sData.map((d, i) => ({
        value: [sTime[i], d.toFixed(2)],
        label: {
          show: true,
          position: 'inside',
          formatter: (params) => Math.round(params.value[1]), // Display the value as an integer
          fontSize: 10, // Adjust the font size here
          color: 'black', // Font color
          fontWeight: 'semi bold', // Make the label text bold
        },
        // Add a class for CSS styling
        itemStyle: {
          color: {
            type: 'linear',
            x: 0, // Start from left
            y: 0,
            x2: 0, // End at right
            y2: 1,
            colorStops: [
              {
                offset: 0,
                color: '#83D475', // Start color
              },
              {
                offset: 1,
                color: '#2EB62C', // End color
              },
            ],
          },
        },
      })),
    };
  } else {
    // Line chart for Daily_average (moving average)
    return {
      name: legendName, // Use the renamed legend name
      type: 'line',
      showSymbol: true,
      symbol: 'circle', // You can choose a different symbol if desired
      data: sData.map((d, i) => ({
        value: [sTime[i], d.toFixed(2)],
        label: {
          show: true,
          position: 'top',
          formatter: (params) => Math.round(params.value[1]), // Display the value as an integer
          fontSize: 10, // Adjust the font size here
          color: 'white', // Font color
        },
        itemStyle: {
          color: 'gold', // Line color
        },
      })),
    };
  }
});

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'axis',
  },
  legend: {
    left: '0',
    bottom: '0',
    data: data.series.map((s) => {
      // Use the renamed legend name
      if (s.refId === 'A') {
        return 'Total Orders';
      } else if (s.refId === 'B') {
        return 'Moving Average';
      } else {
        return legendName; // Use the modified legendName variable
      }
    }),
    itemStyle: {
      color: '#5dc449',
    },
    textStyle: {
      color: 'rgba(128, 128, 128, .9)',
    },
  },
  toolbox: {
    feature: {
      dataZoom: {
        yAxisIndex: 'none',
        icon: {
          zoom: 'path://',
          back: 'path://',
        },
      },
      saveAsImage: {},
    },
  },
  xAxis: {
    type: 'time',
    // minInterval: 0,
    maxInterval: 3600 * 1000 * 24,
    // interval:1,
    min: 'dataMin',
    max: 'dataMax',

    axisTick: {
      alignWithLabel: true,
      interval: 1
    },
    // axisPointer: {
    //   label: {
    //     formatter: function (params) {
    //       return (
    //         'Precipitation  ' +
    //         params.value +
    //         (params.seriesData.length ? '：' + params.seriesData[0].data : '')
    //       );
    //     }
    //   },
    // },
    axisLabel: {
      show: true,
      interval: "auto",
      // showMinLabel: true,
      align: "left",
      // formatter: function (value, index) {
      //   return value + 'kg';
      // }
    },
    splitLine: {
      show: false, // Remove gridlines
    },
  },
  yAxis: {
    type: 'value',
    splitLine: {
      show: false, // Remove gridlines
    },
  },
  grid: {
    left: '2%',
    right: '2%',
    top: '2%',
    bottom: 60, // Adjust the bottom value to accommodate labels
    containLabel: true,
    borderWidth: 0, // Remove gridlines (borders)
  },
  series,
};
